// ─── File: src/main/java/com/bank/bulk/model/Account.java ───
package com.bank.bulk.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "acct_gen")
    @SequenceGenerator(name = "acct_gen", sequenceName = "account_seq", allocationSize = 100)
    private Long id;   // SEQUENCE (not IDENTITY) → inserts can batch

    private String holderName;
    private BigDecimal balance = BigDecimal.ZERO;

    protected Account() { }
    public Account(String holderName) { this.holderName = holderName; }
}
```

