package com.bank.bulk.service;

import com.bank.bulk.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Slf4j
public class BulkImportService {

    @PersistenceContext
    private EntityManager em;

    private static final int BATCH = 100;

    // (Avoid) NAIVE: every entity stays managed → heap grows → OOM on large files
    @Transactional
    public void naiveImport(List<String> names) {
        for (String name : names) {
            em.persist(new Account(name));   // context grows unbounded
        }
        log.warn("Naive import keeps {} entities in context — memory risk", names.size());
    }

    // (Recommended) CORRECT: flush + clear every BATCH rows → context size bounded to BATCH
    @Transactional
    public void batchImport(List<String> names) {
        int i = 0;
        for (String name : names) {
            em.persist(new Account(name));
            if (++i % BATCH == 0) {
                em.flush();   // push this batch's INSERTs (one JDBC batch of 100)
                em.clear();   // detach all → free memory for the next batch
                log.info("Imported {} accounts; context cleared", i);
            }
        }
        em.flush();  // flush the final partial batch
        log.info("Bulk import complete: {} accounts (memory stayed flat)", names.size());
    }
}
```
